CREATE TABLE IF NOT EXISTS usecase_inference_object (id INTEGER PRIMARY KEY AUTOINCREMENT, usecase_id INTEGER NOT NULL REFERENCES master_usecase(id) ON DELETE CASCADE, inference_id INTEGER NOT NULL REFERENCES master_inference(id) ON DELETE CASCADE, object_id INTEGER NOT NULL REFERENCES master_object(id) ON DELETE CASCADE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME, created_by TEXT, updated_by TEXT, deleted_at DATETIME, deleted_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS uq_sqlite_usecase_inference_object_active ON usecase_inference_object(usecase_id, inference_id, object_id) WHERE deleted_at IS NULL;
